@staticmethod
def _is_piece_of(part: str, label: str) -> bool:
    """True when ``part`` occurs inside ``label`` on unit boundaries.

    The boundary test keeps a short answer that merely spells part of a longer
    word (a substring of a label in a spaced language) from being reported as a
    truncated label.
    """
    if not part or part == label or len(part) >= len(label):
        return False
    return re.search(rf"(?<!\w){re.escape(part)}(?!\w)", label) is not None

@staticmethod
def _extract(text: str) -> str:
    if '"final_answer"' not in text:
        return text
    match = re.search(r'"final_answer"\s*:\s*"((?:[^"\\]|\\.)*)"', text)
    if not match:
        return text
    try:
        return json.loads(f'"{match.group(1)}"')
    except json.JSONDecodeError:
        return match.group(1)

@staticmethod
def _required_markup(question: str) -> list[str]:
    if not question:
        return []
    tags = re.findall(r"\[[^\[\]\s]{1,24}\]", question)
    tags += [f"<{name}>" for name in re.findall(r"<([A-Za-z_][A-Za-z0-9_]{0,11})>", question)]
    unique: list[str] = []
    for tag in tags:
        if tag not in unique:
            unique.append(tag)
    return unique[:4]

@staticmethod
def _unbalanced(text: str) -> str:
    for opener, closer in {"(": ")", "[": "]", "{": "}"}.items():
        if text.count(opener) != text.count(closer):
            return f"{opener}{closer}"
    return ""

